const body = $input.first().json.body;
const valid = body && typeof body === 'object' && !Array.isArray(body)
  && typeof body.whatsAppId === 'string' && /^[0-9]{10,15}$/.test(body.whatsAppId)
  && ['pickup', 'delivery'].includes(body.fulfillment?.toLowerCase());

if (!valid) return [{json: {valid: false, error: 'invalid_request'}}];

const fulfillment = body.fulfillment.toLowerCase();
if (fulfillment === 'delivery') {
  if (!body.deliveryAddress || typeof body.deliveryAddress !== 'string' || body.deliveryAddress.trim().length < 5) {
    return [{json: {valid: false, error: 'delivery_address_required'}}];
  }
}

return [{json: {
  valid: true,
  whatsAppId: body.whatsAppId,
  fulfillment: fulfillment.charAt(0).toUpperCase() + fulfillment.slice(1),
  deliveryAddress: body.deliveryAddress?.trim() || null,
  deliveryLandmark: body.deliveryLandmark?.trim() || null,
  notes: body.notes?.trim() || null
}}];

const response = $input.first().json;
const customer = $('Get customer session').first().json.body?.customer;
const checkoutReq = $('Validate checkout request').first().json;

if (!response || response.error || (response.statusCode && response.statusCode >= 400)) {
  const errorMsg = response.body?.error || 'Checkout failed';
  let userMessage = 'Sorry, checkout failed. ';
  if (errorMsg.includes('Cart not found') || errorMsg.includes('empty')) {
    userMessage += 'Your cart is empty. Add some items first!';
  } else {
    userMessage += 'Please try again.';
  }
  return [{json: {
    ok: false,
    error: errorMsg,
    reply: userMessage,
    httpStatus: response.statusCode || 500
  }}];
}

const order = response.body;
const formatPrice = (minor) => (minor / 100).toFixed(2);

const itemsSummary = order.items.map(i => `${i.quantity}× ${i.name}`).join(', ');
let reply = `Order ${order.orderNumber} created!\n\n`;
reply += `Items: ${itemsSummary}\n`;
reply += `Subtotal: GHS ${formatPrice(order.subtotalMinor)}\n`;
if (order.deliveryFeeMinor > 0) reply += `Delivery: GHS ${formatPrice(order.deliveryFeeMinor)}\n`;
reply += `Total: GHS ${formatPrice(order.totalMinor)}\n\n`;
reply += order.fulfillment === 'Delivery' 
  ? `Delivering to: ${order.deliveryAddress}\n`
  : 'Ready for pickup.\n';
reply += '\nReply with your payment method: Paystack, MoMo, or Bank Transfer.';

return [{json: {
  ok: true,
  orderId: order.id,
  orderNumber: order.orderNumber,
  customerId: customer?.id,
  status: order.status,
  fulfillment: order.fulfillment,
  subtotal: formatPrice(order.subtotalMinor),
  deliveryFee: formatPrice(order.deliveryFeeMinor),
  total: formatPrice(order.totalMinor),
  items: order.items.map(i => ({name: i.name, quantity: i.quantity, unitPrice: formatPrice(i.unitPriceMinor), lineTotal: formatPrice(i.lineTotalMinor)})),
  reply,
  httpStatus: 201
}}];
